steps = [
    step("12 个优先级都是 1 的任务按 t0..t11 入队,出队顺序是 [t0, t11, t10, t9, t8, t7, t6, t5, t4, t3, t2, t1]——相同优先级不保证先进先出。加上序号作第二比较键(thenComparingLong(seq))后是 [t0, t1, …, t11]。依次放入 9 3 7 1 8 2 6:toString() = [1, 3, 2, 9, 8, 7, 6](堆数组的顺序),poll 顺序 = [1, 2, 3, 6, 7, 8, 9],stream 的顺序与 toString 相同——只有 poll / take 保证优先级顺序,遍历不保证。没有比较器时 put(new Object()) 抛 ClassCastException(cannot be cast to class java.lang.Comparable)。", t=tl(S(1)), done=lidx(S(1), '12 个优先级都是 1 的任务', '加上序号作第二比较键'), mark=lidx(S(1), 'toString() = [1, 3, 2, 9, 8, 7, 6]', '没有比较器时 put'), kv=KV([['相同优先级', '出队 [t0, t11, t10, …, t1],不是先进先出'], ['加序号作第二比较键', '[t0, t1, …, t11]'], ['toString / stream', '堆数组顺序,不是优先级顺序']], ['相同优先级'])),
    step("元素入队后改变它的优先级:j0..j5 的优先级是 10..15,把 j5 改成 1 之后(没有重新入队),peek() 仍是 j0:10,poll 顺序是 [j0:10, j5:1, j1:11, j2:12, j3:13, j4:14]——j5 排在 j0 之后,位置是错的;先 remove(j5) 再改再 put,poll 顺序是 [j5:1, j0:10, …] 才对。队列不会观察到元素字段的变化,比较键必须是入队后不变的。", t=tl(S(2)), done=lidx(S(2), 'j5 的优先级改成 1 之后'), mark=lidx(S(2), '先 remove 再改再 put'), kv=KV([['直接改优先级', 'peek() 仍是 j0,j5 排在第二'], ['remove → 改 → put', 'j5:1 排第一']], ['直接改优先级'])),
    step("低优先级饥饿:先积压 500 个高优先级任务,之后每毫秒新到 3 个高优先级任务(约 3000 个/秒),消费者每个处理 0.5 ms(约 2000 个/秒),看 1 个 prio 100 的低优先级任务。纯按 prio 排序:3 秒内处理了 6003 个任务,低优先级任务一直没有被取到,队列里积压 471。改成按“创建时间 + prio × 20 ms”排序(越旧越优先):3 秒内处理 6017 个,低优先级任务在 2224 ms 时被取到(约等于它的 100 × 20 ms 的惩罚)。老化让低优先级任务有上限地等待。", t=tl(S(3)), done=lidx(S(3), '纯按 prio 排序'), mark=lidx(S(3), '按“创建时间 + prio × 20 ms”排序'), b=bars([['纯按 prio:低优先级等待', 3000, '> 3000 ms,未被取到'], ['加老化:低优先级等待', 2224, '2224 ms']], 3000, done=[0, 1]), kv=KV([['纯 prio 排序', '3 秒内低优先级任务未被取到,积压 471'], ['按创建时间 + prio × 20 ms', '2224 ms 时被取到']], ['纯 prio 排序'])),
    step("PriorityBlockingQueue 没有容量上限:生产者持续放入 1 KiB 数组,-Xmx64m 下放入 62809 个(约 61 MiB)后抛 OutOfMemoryError: Java heap space。用 Semaphore(1000) 给它限界(生产前 acquire、消费后 release),消费者每个 1 ms:2 秒内生产 2322 个、消费 1322 个,队列里稳定在 1000 个,没有 OOM。优先级队列不会拒绝或阻塞生产者,需要自己加背压。", t=tl(S(4)), done=lidx(S(4), '无界队列 put 持续放入'), mark=lidx(S(4), '用 Semaphore(1000) 限界'), b=bars([['无界 put:OOM 前放入', 62809, '62809 个'], ['Semaphore 限界:队列上限', 1000, '1000 个']], 62809, done=[0, 1]), kv=KV([['无界(-Xmx64m)', '放入 62809 个后 OutOfMemoryError'], ['Semaphore(1000)', '队列稳定在 1000,无 OOM']], ['无界(-Xmx64m)'])),
]
